  function requireConnection() {if(!remoteClient||!connected)throw Error('Connect GitHub first. Your local drafts remain available.');}
  async function loadRemote() {
    requireConnection();const ref=$('repo-branch').value.trim(),path=$('repo-path').value.trim();
    const project=p(),client=remoteClient,repo=connected.repository;
    const load=async()=>{
      const sequence=++remoteLoadSequence,before=project.remote,beforeContent=before.content;
      toast('Reading the repository file…');const result=await client.loadFile(path,ref);
      if(sequence!==remoteLoadSequence)return;
      if(project.remote!==before||before.content!==beforeContent)throw Error('Your repository draft changed while the file was loading. It was kept intact. Back it up or save it, then load again.');
      if(result.content.length>1048576)throw Error('This file is larger than the editor limit.');
      project.remote={repository:repo,path:result.path,branch:ref,sha:result.sha,commitSha:'',content:result.content,loadedContent:result.content};save();if(p()===project)render();toast('File loaded. Changes will stay local until you save a commit.');
    };
    if(p().remote.content!==p().remote.loadedContent)confirmAction('Replace the current file draft?','The current repository file has unsaved edits. Back up this workspace before loading a different file if you want to keep them.',load,'Load selected file');else await load();
  }
