    if(release&&!C.sha(ref))throw Error('Enter the full 40-character tested commit before reading its checks.');
    if(release&&(!/^[A-Za-z0-9_.-]+\.ya?ml$/.test(project.release.workflow)||project.release.workflow==='studio-csharp.yml'))throw Error('Identify the product’s actual CI workflow filename. The C# practice workflow does not verify a product release.');
